UPDATE public.course_offering_meeting AS m
SET classroom  = s.classroom,
    room_id    = r.id,
    updated_at = NOW()
FROM src s
LEFT JOIN public.campus cp ON cp.code = s.campus_code
LEFT JOIN public.room r
  ON r.campus_id = cp.id AND r.building = s.building AND r.number = s.number
WHERE m.id = s.meeting_id;

